using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Server;

namespace ApiMcpServer.Tools;

/// <summary>
/// MCP tools that wrap a REST API. Uses constructor injection for HttpClient
/// so the SDK manages the instance via DI — it never appears in the tool schema.
/// </summary>
[McpServerToolType]
public class WeatherApiTools(HttpClient httpClient, ILogger<WeatherApiTools> logger)
{
    private static readonly JsonSerializerOptions JsonOptions = new() { WriteIndented = true };

    [McpServerTool, Description("Get the current weather forecast for a city.")]
    public async Task<string> GetWeather(
        [Description("City name, e.g. 'Seattle' or 'London'")] string city,
        [Description("Temperature unit: 'celsius' or 'fahrenheit'")] string unit = "celsius",
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Fetching weather for {City} in {Unit}", city, unit);

        var response = await httpClient.GetAsync(
            $"/v1/weather?city={Uri.EscapeDataString(city)}&unit={Uri.EscapeDataString(unit)}",
            cancellationToken);

        response.EnsureSuccessStatusCode();
        return await response.Content.ReadAsStringAsync(cancellationToken);
    }

    [McpServerTool, Description("List all cities that have weather stations available.")]
    public async Task<string> ListCities(CancellationToken cancellationToken = default)
    {
        var response = await httpClient.GetAsync("/v1/cities", cancellationToken);
        response.EnsureSuccessStatusCode();

        var json = await response.Content.ReadAsStringAsync(cancellationToken);
        return json;
    }

    [McpServerTool(ReadOnly = false, Idempotent = true),
     Description("Subscribe to daily weather alerts for a city.")]
    public async Task<string> SubscribeAlerts(
        [Description("City to subscribe to")] string city,
        [Description("Email address for alerts")] string email,
        CancellationToken cancellationToken = default)
    {
        var payload = JsonSerializer.Serialize(new { city, email }, JsonOptions);
        var content = new StringContent(payload, System.Text.Encoding.UTF8, "application/json");

        var response = await httpClient.PostAsync("/v1/alerts/subscribe", content, cancellationToken);
        response.EnsureSuccessStatusCode();

        return await response.Content.ReadAsStringAsync(cancellationToken);
    }
}

